import React, { useState, useEffect } from 'react';
import WeatherWidget from './WeatherWidget';
import ForecastWidget from './ForecastWidget';
import CitySelector from './CitySelector';
import BackgroundHandler from './BackgroundHandler';
import { fetchWeatherData } from '../services/api';

const App = () => {
  const [weatherData, setWeatherData] = useState(null);
  const [city, setCity] = useState('Moscow');
  const [coordinates, setCoordinates] = useState({ lat: 55.7558, lon: 37.6173 }); // Default Moscow coordinates

  useEffect(() => {
    const intervalId = setInterval(() => fetchData(), 3 * 60 * 60 * 1000); // Auto-refresh every 3 hours
    return () => clearInterval(intervalId);
  }, []);

  useEffect(() => {
    fetchData();
  }, [city]);

  const fetchData = async () => {
    try {
      const data = await fetchWeatherData(city);
      setCoordinates({ lat: data.lat, lon: data.lon });
      setWeatherData(data.weatherData);
      console.log('Received weather data:', data.weatherData); // Логируем полученные данные
    } catch (error) {
      console.error('Error fetching weather data:', error);
    }
  };

  return (
    <div className="app-container">
      <BackgroundHandler weatherData={weatherData} />
      <CitySelector onCityChange={setCity} />
      {weatherData && (
        <>
          <WeatherWidget weatherData={weatherData} />
          <ForecastWidget weatherData={weatherData} />
        </>
      )}
    </div>
  );
};

export default App;
